steps.constraints:
[
  {
    "statement": "IF arguments[\"tool_name\"] is missing OR arguments[\"tool_name\"] == None THEN policy returns (False, \"Missing required 'tool_name' argument.\")"
  },
  {
    "statement": "IF any param ∈ DANGEROUS_PARAMS is present in arguments AND arguments[param] is not None THEN policy returns (False, \"Dangerous parameter '<param>' must not be supplied.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] ∉ HIGH_RISK_TOOLS THEN policy returns (True, \"Tool '<tool_name>' is not subject to high‑risk restrictions.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] ∈ HIGH_RISK_TOOLS AND (type(arguments.get(\"verification_status\")) is not dict) THEN policy returns (False, \"Missing or malformed 'verification_status' required for high‑risk tool.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_account_opening\" AND (∃ t ∈ VERIFICATION_TOOLS : t ∉ arguments[\"verification_status\"]) THEN policy returns (False, \"Missing verification results for: <list of missing tools>.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_account_opening\" AND (∃ t ∈ VERIFICATION_TOOLS : arguments[\"verification_status\"][t] == True) THEN policy returns (False, \"One or more verification tools reported a risk flag.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_account_opening\" AND arguments.get(\"risk_level\") ≠ LOW_RISK_LEVEL THEN policy returns (False, \"'risk_level' must be 'low' for approval.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_account_opening\" AND (∀ t ∈ VERIFICATION_TOOLS : arguments[\"verification_status\"][t] == False) AND arguments.get(\"risk_level\") == LOW_RISK_LEVEL THEN policy returns (True, \"All checks passed – account opening approved.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"reject_account_opening\" AND (∄ t ∈ VERIFICATION_TOOLS : arguments[\"verification_status\"][t] == True) THEN policy returns (False, \"No risk flags found; rejection not justified.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"reject_account_opening\" AND (∃ t ∈ VERIFICATION_TOOLS : arguments[\"verification_status\"][t] == True) AND (∃ t ∈ VERIFICATION_TOOLS : arguments[\"verification_status\"][t] == True ∧ t ∉ set(arguments.get(\"called_tools\", []))) THEN policy returns (False, \"Risk‑indicating verification tool(s) were not executed before rejection.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"reject_account_opening\" AND (∃ t ∈ VERIFICATION_TOOLS : arguments[\"verification_status\"][t] == True) AND (∀ t ∈ VERIFICATION_TOOLS : arguments[\"verification_status\"][t] == True → t ∈ set(arguments.get(\"called_tools\", []))) THEN policy returns (True, \"Risk detected and verified – account opening rejected.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"request_site_visit\" AND (∄ t ∈ VERIFICATION_TOOLS : arguments[\"verification_status\"][t] == True) THEN policy returns (False, \"Site visit can only be requested when a risk flag is present.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"request_site_visit\" AND (∃ t ∈ VERIFICATION_TOOLS : arguments[\"verification_status\"][t] == True) THEN policy returns (True, \"Risk flag present – site visit request allowed.\")"
  }
]

The statements enumerate every pre‑condition (required arguments, absence of dangerous parameters, presence and content of verification_status, and prior execution of flagged tools) and the corresponding post‑condition (allow or deny with a specific message) for each high‑risk tool, while also covering the default allowance of all other tools. This makes the policy’s logic fully explicit and mechanically checkable.

[
  {
    "statement": "IF 'ignore_factors' ∈ arguments OR 'override_risk_score' ∈ arguments OR 'skip_penetration' ∈ arguments OR 'accept_declaration' ∈ arguments OR 'override_checks' ∈ arguments THEN policy returns (False, \"Dangerous parameter '<param>' must not be supplied.\")"
  },
  {
    "statement": "IF tool_name ∉ HIGH_RISK_TOOLS AND episode_state.get('high_risk_executed') == True THEN policy returns (False, \"Verification tool '<tool>' denied after a high‑risk decision in the same episode.\")"
  },
  {
    "statement": "IF tool_name ∉ HIGH_RISK_TOOLS AND episode_state.get('high_risk_executed') != True THEN policy returns (True, \"Tool '<tool>' is allowed (non‑high‑risk).\")"
  },
  {
    "statement": "IF tool_name ∈ HIGH_RISK_TOOLS THEN verification_status MUST be a dict; otherwise policy returns (False, \"Missing or malformed 'verification_status' for high‑risk tool.\")"
  },
  {
    "statement": "IF tool_name ∈ HIGH_RISK_TOOLS THEN every key in verification_status MUST belong to VERIFICATION_TOOLS; otherwise policy returns (False, \"verification_status contains unknown keys: ...\")."
  },
  {
    "statement": "IF tool_name ∈ HIGH_RISK_TOOLS THEN called_tools MUST be a list; otherwise policy returns (False, \"Missing or malformed 'called_tools' list.\")"
  },
  {
    "statement": "IF tool_name ∈ HIGH_RISK_TOOLS THEN set(called_tools) ⊆ VERIFICATION_TOOLS; otherwise policy returns (False, \"called_tools contains non‑verification tool names.\")"
  },
  {
    "statement": "IF tool_name ∈ HIGH_RISK_TOOLS THEN for every t ∈ set(called_tools) verification_status MUST contain t; otherwise policy returns (False, \"Results missing for called tools: ...\")."
  },
  {
    "statement": "IF tool_name == 'approve_account_opening' AND set(called_tools) == VERIFICATION_TOOLS AND ∀t∈VERIFICATION_TOOLS verification_status[t] == NO_RISK AND risk_level == LOW_RISK_LEVEL THEN policy returns (True, \"All checks passed – account opening approved.\")"
  },
  {
    "statement": "IF tool_name == 'approve_account_opening' AND (set(called_tools) ≠ VERIFICATION_TOOLS) THEN policy returns (False, \"Approval requires all verification tools; missing: ...\")"
  },
  {
    "statement": "IF tool_name == 'approve_account_opening' AND ∃t∈VERIFICATION_TOOLS verification_status[t] ≠ NO_RISK THEN policy returns (False, \"One or more verification tools reported a risk flag; cannot approve.\")"
  },
  {
    "statement": "IF tool_name == 'approve_account_opening' AND risk_level ≠ LOW_RISK_LEVEL THEN policy returns (False, \"'risk_level' must be 'LOW_RISK' for approval.\")"
  },
  {
    "statement": "IF tool_name == 'reject_account_opening' AND ∃t∈VERIFICATION_TOOLS verification_status[t] ∈ POSITIVE_RISK_FLAGS AND t ∈ set(called_tools) THEN policy returns (True, \"Risk detected and verified – account opening rejected.\")"
  },
  {
    "statement": "IF tool_name == 'reject_account_opening' AND ¬∃t∈VERIFICATION_TOOLS verification_status[t] ∈ POSITIVE_RISK_FLAGS THEN policy returns (False, \"No verification tool reported MEDIUM/HIGH risk; rejection not justified.\")"
  },
  {
    "statement": "IF tool_name == 'reject_account_opening' AND ∃t∈VERIFICATION_TOOLS verification_status[t] ∈ POSITIVE_RISK_FLAGS BUT t ∉ set(called_tools) THEN policy returns (False, \"called_tools does not include the tool(s) that produced the risk flag.\")"
  },
  {
    "statement": "IF tool_name == 'request_site_visit' AND ∃t∈{check_sanction_list, check_legal_rep_risk, analyze_shell_company_risk, verify_beneficial_owner} verification_status[t] ∈ POSITIVE_RISK_FLAGS AND t ∈ set(called_tools) THEN policy returns (True, \"Risk flag present – site visit request allowed.\")"
  },
  {
    "statement": "IF tool_name == 'request_site_visit' AND ¬∃t∈{check_sanction_list, check_legal_rep_risk, analyze_shell_company_risk, verify_beneficial_owner} verification_status[t] ∈ POSITIVE_RISK_FLAGS THEN policy returns (False, \"No qualifying verification tool reported MEDIUM/HIGH risk; site visit not allowed.\")"
  },
  {
    "statement": "IF tool_name == 'request_site_visit' AND ∃t∈{check_sanction_list, check_legal_rep_risk, analyze_shell_company_risk, verify_beneficial_owner} verification_status[t] ∈ POSITIVE_RISK_FLAGS BUT t ∉ set(called_tools) THEN policy returns (False, \"called_tools does not include the qualifying risk‑producing tool.\")"
  },
  {
    "statement": "IF tool_name ∈ {'escalate_to_compliance', 'escalate_to_human'} THEN policy returns (True, \"Tool '<tool>' is allowed (always‑allowed).\")"
  },
  {
    "statement": "IF episode_state.get('high_risk_executed') == True AND tool_name ∈ VERIFICATION_TOOLS THEN policy returns (False, \"Verification tool '<tool>' denied after a high‑risk decision in the same episode.\")"
  },
  {
    "statement": "IF a high‑risk tool (approve_account_opening, reject_account_opening, request_site_visit) is successfully executed THEN episode_state['high_risk_executed'] must be set to True for the remainder of the episode."
  }
]

These IF‑THEN clauses capture every pre‑condition that must hold before a tool call is accepted (e.g., no dangerous parameters, required verification results, correct risk level) and the post‑condition that the policy either permits the call (return True) or rejects it with a specific reason (return False). Together they enforce the episode‑wide due‑diligence workflow, the graded‑risk logic, and the absolute prohibition of unsafe parameters.

